        "speaker": "KELSEY",
        "text": "So I don't like movies and TV shows that are intentionally sad and, like, will make me cry. I don't like to cry. Um, but I have not read, like, a sad book, like a book that's made me cry. Well, no, I've definitely cried reading a book, but not because, like, the book was intentionally, like, a sad book, you know? Do you know what I mean? Like, the genre is just sad.",
