            "nuance_ko": "핵심은 뒷부분이에요. 'I've definitely X'로 사실은 깔끔하게 인정하고, 'but not because Y'로 상대가 떠올릴 법한 이유만 딱 잘라 내요. '그런 일은 있었지만 원인은 그게 아니다'라고 사실과 이유를 분리하는 틀이라, 단순히 말을 바꾸는 정정('well, actually')보다 훨씬 정확하고 방어적이지 않게 들려요. 앞의 'Well, no'는 방금 한 말을 스스로 뒤집는 신호인데, 원어민은 이렇게 말하면서 고쳐 말하는 걸 자연스럽게 여겨서 오히려 신중한 사람처럼 들려요. 회고 회의에서 '일정이 밀린 적은 있지만 우리 쪽 문제는 아니었다'처럼 원인을 바로잡을 때 딱 좋아요.",
            "work_example_en": "We've never missed a deadline with this client. Well, no, we definitely slipped once last spring, but not because of anything on our end.",
