        "ko": "그다음엔 느낌이 딱 오면 하면서 바로 음악이랑 자막을 넣거나, 아니면 2차 편집 때 음악, 자막, 나머지를 한꺼번에 넣어요. 근데 요즘은 그 둘을 합쳐서 한 번에 싹 끝내는 게 좋더라고요. 이번 영상은 첫 번째 방식으로 했어요. 쭉 보면서 먼저 다 잘라내고, 그 위에 이것저것 얹었죠. 근데 그건 영상마다 달라요. 궁금하셨던 분들을 위해 제 편집 과정을 살짝 보여드렸어요.",
