            "nuance_ko": "미리 다 계획하지 않고 진행하면서 동시에 처리한다는 뜻. 'at the same time'보다 '흐름 타며 바로바로'라는 느낌이 있어요. 직장에선 'We'll figure it out as we go(하면서 맞춰가죠)'나 'I'll update the doc as I go'처럼 정말 자주 들려요.",
